import {executionPanel,executionView,decisionExplanation} from './execution-view-f1b717ac6ba642f9.js';
export function terminal({snapshot:s,state,icon,e,num,money,pct,human,date,chart,sourceMode,automation,controlAllowed=true}) {
 const data=s.intraday||{},paper=s.paper||{},settings=s.settings||{};
 const all=data.bars||[],sessions=[...new Set(all.map(b=>b.timestamp.slice(0,10)))].sort();
 const session=sessions.includes(state.session)?state.session:sessions.at(-1);
 let bars=all.filter(b=>b.timestamp.startsWith(session||'none'));
 const current=bars.at(-1)||{},first=bars[0]||{},isVix=state.instrument==='vix';
 const lastValue=isVix?current.VIX:current.Close,change=isVix?(current.VIX-first.VIX):(current.Close-first.Open);
 const local=['local','cloud'].includes(sourceMode),enabled=local&&automation.enabled,offline=sourceMode.endsWith('disconnected');
 const capital=paper.realised_equity_rs??500000,budget=capital*(settings.RISK_PER_TRADE||.02);
 const position=paper.position||null,engineState=offline?'paper_engine_disconnected':local?(automation.state||'stopped'):'hosted_snapshot';
 const pctChange=(first.Open&&current.Close)?(current.Close/first.Open-1)*100:0;
 const watch=(label,value,delta,key,sub)=>`<button class="watch-row ${state.instrument===key?'active':''}" data-action="watch" data-value="${key}"><span><strong>${label}</strong><small>${sub}</small></span><span class="watch-price"><b>${num(value,2)}</b><small class="${delta<0?'negative':'positive'}">${delta>=0?'+':''}${num(delta,2)}</small></span></button>`;
 const execution=executionView(s,automation,sourceMode);
 const statusLabel=human(engineState);
 const q=s.reports.find(r=>r.algorithm==='adaptive_intraday'),btest=q?.summary?.[0];
 let chartHtml;
 if(isVix){chartHtml=chart('terminal-vix',[{name:'India VIX',color:'#bd9df2',points:bars.filter(b=>b.VIX!=null).map(b=>[b.timestamp,b.VIX])}],{unit:'index',height:340});}
 else chartHtml=candles(bars,state.candleTimeframe||'5m',e,num,paper.trades||[]);
 return `<div class="terminal-heading"><div><p class="eyebrow">YOUR AUTOMATED OPTIONS WORKSPACE</p><h1>Trading terminal<span class="version-chip">PAPER ACCOUNT</span></h1><p class="subheading">A clear view of the market. A strategy for every qualifying condition.</p></div><div class="terminal-actions"><button class="btn" data-action="run-backtest" ${local&&controlAllowed&&state.paperProfile!=='adaptive25'&&!state.backtestId?'':'disabled'}>${icon('chart')}${state.backtestId?'Backtest running…':'Run intraday backtest'}</button><button class="btn primary" data-action="${offline?'reconnect':'auto-start'}" ${(!local&&!offline)||!controlAllowed||state.controlPending?'disabled':''}>${icon('activity')}${offline?'Reconnect paper engine':state.controlPending==='auto-start'?'Starting…':enabled?'Auto paper enabled':'Start auto paper'}</button></div></div>
 <div class="desk-status ${execution.tone}" role="status"><div class="desk-status-icon">${icon(execution.tone==='blocked'?'shield':local?'activity':'info')}</div><div><strong>${e(execution.title)}</strong><span>${local?`15m bias · 5m entries · ${e(execution.candidate?human(execution.candidate):'No qualifying setup')}`:'Saved research records. Connect your engine to see live activity.'}</span></div><button class="panel-link" data-action="show-decisions">${icon('clock')}Decision log</button></div>
 <div class="market-strip"><div><span class="ticker-name">NIFTY 50</span><strong>${num(current.Close,2)}</strong><small class="${pctChange<0?'negative':'positive'}">${pctChange>=0?'+':''}${num(pctChange,2)}%</small></div><div><span class="ticker-name">INDIA VIX</span><strong>${num(current.VIX,2)}</strong><small>5m observation</small></div><div><span class="ticker-name">VIRTUAL EQUITY</span><strong>${money(capital)}</strong><small>₹5,00,000 initial</small></div><div><span class="ticker-name">RISK / ENTRY</span><strong>${money(budget)}</strong><small>${pct((settings.RISK_PER_TRADE||.02)*100)} equity limit</small></div><div class="market-status"><i class="dot"></i><span data-automation-status>${e(statusLabel)}</span><small>${offline?'SERVER CONNECTION LOST':sourceMode==='cloud'?'HOSTED PAPER ENGINE':local?'LOCAL PAPER ENGINE':'EXPORTED SNAPSHOT'}</small></div></div>
 <div class="terminal-grid"><aside class="terminal-watch panel"><div class="panel-header"><h2 class="panel-title">Marketwatch</h2><span class="tag gray">NSE · MODEL</span></div><div class="watch-tabs"><span class="active">Indices</span><span>Indicators</span></div>${watch('NIFTY 50',current.Close,(current.Close-first.Open),'nifty','Underlying index')}${watch('INDIA VIX',current.VIX,current.VIX-first.VIX,'vix','Volatility index')}<div class="watch-section">MARKET CONDITIONS</div><div class="watch-metric"><span>15m direction</span><b>${e(human(data.condition||'unavailable'))}</b></div><div class="watch-metric"><span>Volatility</span><b>${e(human(data.volatility||'unavailable'))}</b></div><div class="watch-metric"><span>ADX · 15m</span><b>${num(current.adx,1)}</b></div><div class="watch-metric"><span>IV rank</span><b>${num(current.ivr,1)}</b></div><div class="watch-section">SESSION RULES</div><div class="watch-metric"><span>Entries</span><b>09:45–14:30</b></div><div class="watch-metric"><span>Square-off target</span><b class="accent">15:15 IST</b></div><div class="watch-metric"><span>Trades / day</span><b>${num(settings.INTRADAY_MAX_TRADES??3)} maximum</b></div><div class="watch-metric"><span>Daily loss budget</span><b>${pct((settings.INTRADAY_DAILY_LOSS_LIMIT??.03)*100)} of start equity</b></div><div class="watch-note">Weekly option structures. Every position has hedges. No broker orders.</div></aside>
 <section class="terminal-centre"><div class="panel candle-panel"><div class="candle-toolbar"><div><span class="instrument-symbol">${isVix?'VIX':'N50'}</span><div><strong>${isVix?'INDIA VIX':'NIFTY 50'}</strong><span>${isVix?'Volatility index':'Underlying index'} · public research feed</span></div></div><div class="chart-controls"><div class="range-control">${['5m','15m'].map(tf=>`<button data-action="candle-timeframe" data-value="${tf}" class="${state.candleTimeframe===tf?'active':''}" ${isVix&&tf==='15m'?'disabled':''}>${tf}</button>`).join('')}</div><select id="session-select" class="select" aria-label="Intraday chart session">${sessions.map(day=>`<option value="${day}" ${day===session?'selected':''}>${date(day)}</option>`).join('')}</select></div></div><div class="ohlc-strip"><strong class="${change<0?'negative':'positive'}">${num(lastValue,2)}</strong><span>O <b>${num(isVix?first.VIX:current.Open,2)}</b></span>${isVix?'':`<span>H <b>${num(current.High,2)}</b></span><span>L <b>${num(current.Low,2)}</b></span>`}<span>C <b>${num(lastValue,2)}</b></span><small>${e(data.latest_bar?data.latest_bar.slice(11,16)+' IST · '+data.latest_bar.slice(0,10):'Waiting for bars')}</small></div>${chartHtml}<div class="candle-caption"><span><i class="legend-dot" style="background:#56a9e0"></i> EMA 20</span><span><i class="legend-dot" style="background:#d7a66b"></i> EMA 50</span><span>Only completed bars · ${e(data.vix_source||'VIX unavailable')}</span></div></div>
 <div class="panel terminal-book"><div class="book-tabs">${[['positions','Positions'],['orders','Orders'],['history','Trade history'],['activity','Engine activity']].map(([key,label])=>`<button class="${state.bookTab===key?'active':''}" data-action="book-tab" data-value="${key}">${label}${key==='positions'?` <span>${paper.open_trades||0}</span>`:key==='orders'?` <span>${paper.orders?.length||0}</span>`:''}</button>`).join('')}<button class="panel-link" data-action="refresh" style="margin-left:auto">${icon('refresh')}Refresh</button></div>${book(s,state,e,num,money,human,date,icon,sourceMode)}</div></section>
 <aside class="terminal-engine panel"><div class="panel-header"><h2 class="panel-title">Strategy engine</h2><span class="tag ${enabled?'':'gray'}">${enabled?'AUTO PAPER':'PAPER ONLY'}</span></div><div class="engine-body"><div class="engine-status"><div class="pulse-dot ${enabled?'on':''}"></div><div><strong data-automation-status>${e(statusLabel)}</strong><p>${offline?sourceMode==='cloud-disconnected'?'Check the hosted server, then reconnect':'Start the local server, then reconnect':local?'Checking completed bars every 60 seconds':'Connect your cloud engine for live activity'}</p></div></div><div class="engine-candidate"><span>NEXT QUALIFYING STRUCTURE</span><h3>${e(data.candidate?human(data.candidate):'Stand aside')}</h3><p>${e(decisionExplanation(paper.decisions?.at(-1)?.reason||data.reason))}</p></div><div class="data-pair"><span>Market condition</span><strong>${e(human(data.condition))}</strong></div><div class="data-pair"><span>Volatility condition</span><strong>${e(human(data.volatility))}</strong></div><div class="data-pair"><span>Open positions</span><strong>${num(paper.open_trades||0)} / 1</strong></div><div class="data-pair"><span>Hedge width</span><strong>100 points</strong></div><div class="data-pair"><span>Entry risk budget</span><strong>${money(budget)}</strong></div><div class="data-pair"><span>New entries</span><strong>${enabled?'Automatic':'Paused / snapshot'}</strong></div><div class="engine-controls"><button class="btn" data-action="auto-pause" ${local&&controlAllowed&&!state.controlPending?'':'disabled'}>${icon('shield')}Pause new entries</button><small>Pausing entries keeps open-position exit management active.</small></div>${!local?`<a class="btn engine-connect" href="#mobile">${icon('layers')}Connect paper engine</a>`:''}<div class="engine-footnote">Last source bar: ${e(date(data.latest_bar))}. A stale or failed feed blocks new entries. ${sourceMode==='cloud'?'Exit management runs on the hosted server.':local?'Keep the local application running to manage exits.':'Connect to confirm the current engine state.'}</div></div></aside></div>
 ${executionPanel(s,automation,sourceMode,{e,human,num,date,icon})}
 <section class="panel router-panel"><div class="panel-header"><div><h2 class="panel-title">A strategy for each qualifying market</h2><p class="panel-subtitle">Fixed rules · chosen automatically · no parameter fitting</p></div><button class="panel-link" data-action="nav" data-value="compare">Research results</button></div><div class="router-grid">${(data.playbook||[]).slice(0,6).map(rule=>`<div class="router-tile ${data.candidate&&data.candidate===rule.strategy?'current':''}"><span>${e(rule.condition)}</span><strong>${e(rule.strategy?human(rule.strategy):'No trade')}</strong><small>${rule.strategy?.includes('call_spread')||rule.strategy?.includes('put_spread')?'Hedged vertical':rule.strategy==='iron_condor'?'Hedged range structure':'No setup is also a decision'}</small></div>`).join('')}</div></section>
 <div class="terminal-foot"><span>${icon('shield')}Synthetic option prices and fills · public underlying/VIX bars · virtual money only</span><span>${btest?`${num(btest.trades)} recent backtest trades · ${money(btest.total_rs)} / lot after model costs · not validated`:'Backtest results are available in Research'}</span></div>`;
}
function book(s,state,e,num,money,human,date,icon,sourceMode){
 const p=s.paper||{};
 if(state.bookTab==='orders')return ordersView(p,{e,num,money,human,date,icon},{limit:10,compact:true});
 if(state.bookTab==='activity'){
  const events=[...(p.decisions||[])].reverse().slice(0,8);
  return events.length?`${sourceMode==='snapshot'?`<div class="activity-asof">Saved engine decisions through ${e(date(events[0].timestamp||events[0].day))} IST · refresh loads published records only</div>`:''}<div class="table-scroll"><table class="data-table"><thead><tr><th>Bar</th><th>Action</th><th>Market</th><th>Selected strategy</th><th>Reason</th><th class="num">Virtual equity</th></tr></thead><tbody>${events.map(x=>`<tr><td>${e(date(x.day||x.timestamp))}</td><td>${e(human(x.action))}</td><td>${e(human(x.condition))}</td><td>${e(x.candidate?human(x.candidate):'Stand aside')}</td><td>${e(decisionExplanation(x.reason))}</td><td class="num">${money(x.equity_rs??x.equity)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="book-empty">${icon('activity')}<strong>${sourceMode==='snapshot'?'No engine activity in this saved snapshot':'Waiting for a new completed bar'}</strong><p>${sourceMode==='snapshot'?'This public page contains published records. Connect your cloud engine to see live account activity.':'The forward paper account does not backfill historical entries.'}</p></div>`;
 }
 const rows=(p.trades||[]).filter(t=>state.bookTab==='history'?t.status==='closed':t.status==='open');
 if(!rows.length)return `<div class="book-empty">${icon(state.bookTab==='positions'?'layers':'book')}<strong>${state.bookTab==='positions'?'No open paper positions':'No forward paper fills yet'}</strong><p>${state.bookTab==='positions'?'The engine will enter only when the market, trigger, data freshness and risk budget all qualify.':'Historical backtests and forward paper trading are kept separate.'}</p></div>`;
 return `<div class="table-scroll"><table class="data-table"><thead><tr><th>Structure</th><th>Entry</th><th>Expiry</th><th class="num">Lots</th><th>Status</th><th class="num">Net / marked P&L</th></tr></thead><tbody>${rows.map(t=>`<tr><td class="strategy-name">${e(human(t.strategy))}</td><td>${e(date(t.entry_date))}</td><td>${e(date(t.expiry))}</td><td class="num">${num(t.lots)}</td><td>${e(human(t.status))}</td><td class="num ${(t.exit?.net_pnl_rs??t.mark?.net_pnl_rs)<0?'negative':'positive'}">${money(t.exit?.net_pnl_rs??t.mark?.net_pnl_rs,2)}</td></tr>`).join('')}</tbody></table></div>`;
}
function candles(input,timeframe,e,num,trades=[]){
 let bars=input;
 if(timeframe==='15m'){
  const buckets=new Map();for(const b of input){const hh=+b.timestamp.slice(11,13),mm=+b.timestamp.slice(14,16),end=Math.ceil((hh*60+mm)/15)*15,key=b.timestamp.slice(0,10)+'/'+end;const a=buckets.get(key)||[];a.push(b);buckets.set(key,a)}
  bars=[...buckets.values()].filter(a=>a.length===3).map(a=>({...a[2],Open:a[0].Open,High:Math.max(...a.map(b=>b.High)),Low:Math.min(...a.map(b=>b.Low))}));
 }
 if(!bars.length)return '<div class="book-empty"><strong>No complete candles available</strong><p>Refresh the 5-minute feed to populate the chart.</p></div>';
 const W=960,H=340,L=15,R=72,T=15,B=30,pw=W-L-R,ph=H-T-B;
 const fast=timeframe==='15m'?'ema_fast':'trigger_fast',slow=timeframe==='15m'?'ema_slow':'trigger_slow';
 const values=bars.flatMap(b=>[b.High,b.Low,b[fast],b[slow]]).filter(Number.isFinite),min=Math.min(...values),max=Math.max(...values),pad=(max-min||20)*.1,low=min-pad,high=max+pad;
 const x=i=>L+(i+.5)/bars.length*pw,y=v=>T+(high-v)/(high-low)*ph;
 let svg='';for(let i=0;i<5;i++){const v=low+(high-low)*i/4,yy=y(v);svg+=`<line x1="${L}" y1="${yy}" x2="${W-R}" y2="${yy}" stroke="#202c3d"/><text x="${W-R+9}" y="${yy+3}" fill="#7d8aa0" font-size="10">${num(v,1)}</text>`}
 for(let i=0;i<6;i++){const index=Math.round(i/5*(bars.length-1));svg+=`<text x="${x(index)}" y="${H-7}" text-anchor="middle" fill="#7d8aa0" font-size="10">${e(bars[index].timestamp.slice(11,16))}</text>`}
 const width=Math.max(2,Math.min(13,pw/bars.length*.62));
 bars.forEach((b,i)=>{const xx=x(i),green=b.Close>=b.Open,color=green?'#28bd95':'#ed7778',top=Math.min(y(b.Open),y(b.Close)),height=Math.max(1,Math.abs(y(b.Open)-y(b.Close)));svg+=`<g><title>${e(b.timestamp)} | O ${num(b.Open,2)} H ${num(b.High,2)} L ${num(b.Low,2)} C ${num(b.Close,2)}</title><line x1="${xx}" y1="${y(b.High)}" x2="${xx}" y2="${y(b.Low)}" stroke="${color}"/><rect x="${xx-width/2}" y="${top}" width="${width}" height="${height}" rx=".5" fill="${color}"/></g>`});
 for(const [key,color] of [[fast,'#56a9e0'],[slow,'#d7a66b']]){const pts=bars.map((b,i)=>({i,v:b[key]})).filter(p=>Number.isFinite(p.v));const d=pts.map((p,i)=>`${i?'L':'M'}${x(p.i)},${y(p.v)}`).join(' ');svg+=`<path d="${d}" fill="none" stroke="${color}" stroke-width="1.4"/>`}
 for(const trade of trades)for(const [label,stamp] of [['ENTRY',trade.entry_date],['EXIT',trade.exit_date]]){
  if(!stamp||String(stamp).slice(0,10)!==bars[0].timestamp.slice(0,10))continue;
  const at=Date.parse(stamp),index=bars.findIndex(b=>Date.parse(b.timestamp)>=at&&Date.parse(b.timestamp)-at<(timeframe==='15m'?15:5)*60000);
  if(index<0)continue;
  const xx=x(index),yy=label==='ENTRY'?y(bars[index].Low)+9:y(bars[index].High)-9,color=label==='ENTRY'?'#65b5ff':'#ffb44b';
  svg+=`<g aria-label="Paper ${label.toLowerCase()} ${e(stamp)}"><title>Stored paper ${label.toLowerCase()} · ${e(stamp)} · ${e(trade.strategy||'')}</title><circle cx="${xx}" cy="${yy}" r="4" fill="${color}" stroke="#0d1117"/><text x="${xx}" y="${label==='ENTRY'?yy+13:yy-8}" text-anchor="middle" fill="${color}" font-size="9">${label}</text></g>`;
 }
 const last=bars.at(-1),yy=y(last.Close);svg+=`<line x1="${L}" y1="${yy}" x2="${W-R}" y2="${yy}" stroke="#28bd95" stroke-dasharray="4 4" opacity=".65"/><rect x="${W-R}" y="${yy-10}" width="71" height="20" rx="3" fill="#237964"/><text x="${W-R+35}" y="${yy+4}" text-anchor="middle" fill="#e6fff5" font-size="10">${num(last.Close,1)}</text>`;
 return `<div class="candlestick-wrap"><svg class="candlestick-chart" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img" aria-label="Nifty 50 ${timeframe} OHLC candlesticks with EMA20 and EMA50"><title>Actual ${timeframe} underlying candles, model-trading reference only</title>${svg}</svg></div>`;
}

export function ordersView(p,{e,num,money,human,date,icon},{rows=null,limit=0,compact=false,total=null}={}){
 const all=rows||p.orders||[],shown=limit?all.slice(0,limit):all;
 if(!shown.length)return `<div class="book-empty">${icon('book')}<strong>No recorded paper orders</strong><p>BUY and SELL leg fills will appear automatically after a qualifying forward paper entry. No test or backtest fills are added to this account.</p></div>`;
 return `<div class="table-scroll"><table class="data-table order-table"><thead><tr><th>Filled bar · IST</th><th>Contract</th><th>Side</th><th>Position</th><th class="num">Qty · lots</th><th class="num">Fill ₹ / unit</th><th>Status</th><th>Paper order ID</th></tr></thead><tbody>${shown.map(o=>`<tr><td>${e(date(o.filled_at))}</td><td><span class="strategy-name">NIFTY ${num(o.strike)} ${e(o.option_type)}<small>Expiry ${e(date(String(o.expiry).slice(0,10)))} · ${e(human(o.strategy))}</small></span></td><td><span class="tag ${o.side==='BUY'?'':'red'}">${e(o.side)}</span></td><td>${e(o.phase==='OPEN'?'Opening':'Closing')}</td><td class="num">${num(o.lots)}</td><td class="num">${money(o.fill_price,2)}</td><td><span class="tag gray">Modelled fill</span></td><td><code class="order-id">${e(o.order_id)}</code></td></tr>`).join('')}</tbody></table></div><div class="table-foot"><span>${num(shown.length)} of ${num(total??all.length)} recorded fills · virtual execution only</span>${compact?`<button class="panel-link" data-action="nav" data-value="orders">Full order book</button>`:''}</div>`;
}
